'use strict';
const pages=[['home','◈','Command Center'],['discover','⌕','Discover'],['grader','▣','Grade Photos'],['research','◫','Research Lab'],['vault','◇','PSA Vault'],['portfolio','▤','Portfolio & Cash'],['market','⇄','Market & Sources'],['models','◎','Model Lab'],['settings','⚙','Settings']];
let S={},M={},selectedFront=null,selectedBack=null,imageLimit=24;
const $=id=>document.getElementById(id),e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cash=v=>v===null||v===undefined||v===''?'Unknown':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(v));
const badge=(v,cls='')=>`<span class="badge ${cls}">${e(v)}</span>`;
const json=v=>`<pre>${e(JSON.stringify(v,null,2))}</pre>`;
const link=(url,label)=>/^https:\/\//.test(url||'')?`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`:e(label);
const stat=(label,value,sub,cls='')=>`<div class="stat"><div class="label">${e(label)}</div><div class="number ${cls}">${e(value)}</div><small>${e(sub)}</small></div>`;
const empty=(title,body)=>`<div class="empty"><b>${e(title)}</b><p>${e(body)}</p></div>`;
const pageTop=(eyebrow,title,body,action='')=>`<div class="page-top"><div><div class="eyebrow">${e(eyebrow)}</div><h1>${e(title)}</h1><p>${e(body)}</p></div>${action}</div>`;
const field=(name,label,type='text',value='',required=false)=>`<label>${e(label)}<input name="${e(name)}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='number'?'min="0" step="any"':''}></label>`;
const sel=(name,label,values)=>`<label>${e(label)}<select name="${name}">${values.map(v=>`<option value="${e(v)}">${e(v)}</option>`).join('')}</select></label>`;
const check=(name,label)=>`<label><input name="${name}" type="checkbox">${e(label)}</label>`;
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',7000)}
async function api(action,body){let r=await fetch('/api/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-Holy-Local':window.LOCAL_TOKEN},body:JSON.stringify(body)});let data=await r.json();if(!r.ok)throw Error(data.error||'Local request failed');return data}
async function load(){let r=await fetch('/api/state');S=await r.json();M=await (await fetch('/api/monthly')).json();render()}
function download(kind){window.location='/api/export?kind='+encodeURIComponent(kind)}
function page(){return location.hash.slice(1)||'home'}
function render(){const key=page();$('nav').innerHTML=pages.map(([id,icon,name])=>`<a href="#${id}" class="${id===key?'active':''}"><span>${icon}</span>${name}</a>`).join('');$('crumb').textContent=(pages.find(x=>x[0]===key)?.[2]||'WORKSPACE').toUpperCase();const views={home,discover,grader,research,vault,portfolio,market,models,settings};$('content').innerHTML=(views[key]||home)();bind();}
function health(title,sub,status,cls=''){return `<div class="status-row"><div>◇</div><div class="grow"><b>${e(title)}</b><small>${e(sub)}</small></div>${badge(status,cls)}</div>`}
function home(){let a=S.audit,b=S.budget,p=S.providers;let packs=(a.canonical_packs||[]).filter(x=>x.status==='VERIFIED').length;return pageTop('PRIVATE RESEARCH / OVERVIEW','Your edge starts with evidence.','Condition, capital and provenance. One workspace for the complete card journey.',`<a class="button" href="#discover">Explore opportunities →</a>`)+
`<div class="grid stats">${stat('INITIAL TEST CAPITAL',cash(b.first_batch_cap),`${cash(b.all_in_committed)} known committed`)}${stat('RESEARCH OBSERVATIONS',S.research.length,'Source rows · physical copies unresolved')}${stat('ORIGINALS INDEXED',a.source_files||0,`${((a.bytes||0)/1e9).toFixed(2)} GB · immutable local sources`)}${stat('REAL GRADER',S.real_trained_grader?'Experimental':'No model','Verified photo/outcome linkage required','gold')}</div>
<div class="grid two"><section class="panel hero"><div class="eyebrow">THE CONDITION LAB</div><h1>Inspect the card.<br>Understand the risk.</h1><p>Review original front and back photographs, record visible defects, isolate label-free views and trace each observed grading result to a physical card.</p>${badge('HUMAN REVIEW REQUIRED','gold')}<div class="actions"><a class="button" href="#grader">Open Grade Photos →</a><a class="button secondary" href="#models">Training coverage</a></div><small>Zero verified pre-buy photo/outcome pairs at the initial audit. No real-data training accuracy is claimed.</small></section>
<section class="panel"><h2>Source & provider health</h2>${health('Fredy research',`${packs} / 18 canonical archives verified`,'LOCAL','blue')}${health('eBay Browse','Authorized active-listing discovery',p.ebay_browse.enabled&&p.ebay_browse.production_approved?'CONFIGURED':'OFFLINE')}${health('PSA Vault','Owner imports · custody · receipts','MANUAL','blue')}${health('Condition model','Paired CNN pipeline · real labels pending','NOT TRAINED','gold')}</section></div>
<div class="grid two"><section class="panel"><div class="panel-head"><div><h2>Creator business reference</h2><p>February–September 2026 · reported figures, not audited cash</p></div>${badge('HISTORICAL')}</div><div class="chart"><div class="bars">${(M.months||M.rows||[]).map(r=>`<div class="bar" style="height:${Math.max(4,Number(r.revenue||r.reported_revenue||0)/1000)}px"><small>${e(r.month||'')}</small></div>`).join('')||'<p>Eight monthly source ledgers available below.</p>'}</div></div><div class="grid three">${stat('SOLD CARDS','506','Creator reported')}${stat('REVENUE','$444,671','Gross source claim')}${stat('PRE-TAX PROFIT','$230,594','Not verified receipts')}</div><div class="actions"><button data-action="monthly" class="secondary">Inspect monthly ledger</button><a href="#research" class="button secondary">Research Lab ↗</a></div></section>
<section class="panel"><h2>Capital guardrails</h2><div class="progress"><span style="width:${Math.min(100,Number(b.all_in_committed)/20)}%"></span></div>${health('Shared first batch','$2,000 across all strategies',b.within_cap?'WITHIN CAP':'OVER CAP',b.within_cap?'blue':'red')}${health('Protected reserve','$5,000 remains unallocated','PROTECTED','green')}${health('Holdings with unknown basis',`${b.unknown_cost_holdings} require full cost evidence`,'REVIEW')}<div class="callout">Research leads remain visible when comps or images are missing. Buying readiness requires exact evidence and a full downside calculation.</div><a href="#portfolio">Review portfolio & cash →</a></section></div>`}
function leadRows(items){return items.map(r=>`<tr><td><b>${e(r.title||r.name||'Untitled lead')}</b><small>${e(r.provider||r.source||'manual')} · ${e(r.observed_at||r.retrieved_at||'unknown date')}</small></td><td>${r.currency==='USD'?cash(r.ask):e(r.ask??'Unknown')+' '+e(r.currency||'currency unknown')}</td><td>${r.priority===null?badge('UNKNOWN'):cash(r.priority)}<small>Hypothetical spread</small></td><td>${badge(r.approval,r.approval==='MANUAL_BUY_READY'?'green':'gold')}<small>${e(r.evidence_gaps.join(' · '))}</small></td><td><button data-action="deal" data-id="${r.id}" class="secondary">Review →</button></td></tr>`)}
function discover(){return pageTop('DISCOVERY / TWO REVIEW LANES','Find the overlooked.','Top 50 research leads and Top 20 premium possibilities. Missing evidence stays visible.',`<button data-action="import-leads">+ Add leads</button>`)+
`<div class="grid stats">${stat('ALL LEADS',S.leads.length,'Authorized active or manually imported')}${stat('PREMIUM RESEARCH',S.leads.filter(r=>Number(r.possible_best_exit)>=500).length,'Illustrative $500+ potential exit')}${stat('MANUAL BUY READY',S.leads.filter(r=>r.approval==='MANUAL_BUY_READY').length,'Strict evidence review remains required')}${stat('WATCHLIST',S.watchlist.length,'Saved local review tasks')}</div>
<div class="toolbar"><input id="leadSearch" placeholder="Search title, year, grader, language, finish…" aria-label="Search leads"><select id="leadSort" aria-label="Queue"><option value="all">Top 50 research</option><option value="premium">Top 20 premium</option><option value="vault">Verified vault observations</option></select><button class="secondary" data-action="export" data-kind="lead">Export CSV</button></div><section class="panel" id="leadResults">${S.leads.length?table(['CARD / SOURCE','ASK','UPSIDE CLUE','EVIDENCE',''],leadRows(S.leads.slice(0,50))):empty('Your discovery queue is ready.','Import a real listing URL or CSV. Historical Fredy examples live in Research Lab and are never presented as current buyable offers.')}<div class="actions"><button data-action="new-lead" class="secondary">Add one listing</button><button data-action="ebay" class="secondary">Search approved eBay API</button></div></section><section class="panel"><h2>Saved watches & searches</h2>${S.watchlist.length?S.watchlist.map(r=>`<div class="source-card"><b>${e(r.subject)}</b><p>${e(r.notes)}</p><small>${e(r.added_at)}</small></div>`).join(''):empty('No watches yet','Save a lead from its review drawer. Refresh is on demand; no live push notifications are claimed.')}</section>`}
function grader(){return pageTop('LOCAL CONDITION LAB','See more. Guess less.','Unaltered originals, paired views and explicit uncertainty. All image processing stays on this Mac.')+
`<div class="grid two"><section class="panel"><h2>Front & back review</h2><div class="photo-pair"><div><label>Front photograph<input type="file" id="frontUpload" accept="image/png,image/jpeg,image/webp"></label>${selectedFront?`<img src="/api/image?id=${selectedFront}" data-action="image" data-id="${selectedFront}" alt="Unaltered front source">`:empty('Front missing','Choose a photograph or select an indexed original below.')}</div><div><label>Back photograph<input type="file" id="backUpload" accept="image/png,image/jpeg,image/webp"></label>${selectedBack?`<img src="/api/image?id=${selectedBack}" data-action="image" data-id="${selectedBack}" alt="Unaltered back source">`:empty('Back missing','Hidden surfaces remain unknown.')}</div></div><div class="actions"><button data-action="infer">Assess evidence</button><button data-action="training-label" class="secondary">Link observed outcome</button></div><div id="inference"></div><div class="callout">Model status: ${S.real_trained_grader?'EXPERIMENTAL':'NO REAL TRAINED MODEL'}. A grade is a grader-specific observed outcome. Photo quality is not a prediction of PSA 10.</div></section>
<section class="panel"><h2>How to review a training example</h2>${[['Select the same physical card','Choose original front and back photographs. Repeated grading attempts share one specimen.'],['Review a card-only crop','Open each image and click two opposite corners around the entire card. Exclude labels, certs, slab branding and subtitles. Preserve every card edge.'],['Verify causal order','Record buyer-visible capture stage and the actual later grader result with evidence. Rejected cards without later outcomes cannot be training labels.'],['Add visible defect observations','Seen, not visible and unknown remain distinct. A numeric grade does not label a scratch.']].map((r,i)=>`<div class="step"><span>${i+1}</span><div><b>${r[0]}</b><p>${r[1]}</p></div></div>`).join('')}</section></div>
<section class="panel"><div class="panel-head"><div><h2>Original evidence gallery</h2><p>${S.images.length} indexed original image assets · choose an image to magnify and review</p></div><button data-action="more-images" class="secondary">Show 24 more</button></div><input id="imageSearch" placeholder="Filter filenames or source archive" aria-label="Filter original images"><div class="image-grid" id="imageGallery" style="margin-top:18px">${gallery(S.images.slice(0,imageLimit))}</div></section>`}
function gallery(rows){return rows.map(r=>`<button data-action="image" data-id="${r.id}" title="${e(r.name)}"><img loading="lazy" src="/api/image?id=${r.id}" alt="Original ${e(r.name)}"><span>${e(r.name)}</span></button>`).join('')}
function discoveryPanel(){let feed=S.discovery||{status:'NOT_STARTED',count:0,leads:[],source_counts:{}};return `<section class="panel" id="discoveryFeed"><div class="panel-head"><div><div class="eyebrow">AUTOMATED RESEARCH DISCOVERY</div><h2 style="margin-top:10px">Active listings → inspection queue</h2><p>${e(feed.count)} collected leads · ${e(feed.status)} · last collector sighting ${e(feed.last_seen||'not started')}</p></div>${badge(feed.live_status||'NO LIVE API OBSERVATIONS',feed.live_status==='API_OBSERVATIONS_PRESENT'?'blue':'gold')}</div><p>Read-only local feed. Research interest is a review priority; asking prices are not sold comps. Imports and API observations retain separate provenance.</p><div class="actions"><button data-action="discovery-import">Import listing CSV</button><button data-action="discovery-sync" class="secondary">Sync into Discover</button><button data-action="discovery-scan" class="secondary">Run one authorized scan</button></div>${feed.leads.length?table(['LISTING / SOURCE','ACTIVE ASK','RESEARCH INTEREST','APP QUEUE',''],feed.leads.map((r,i)=>`<tr><td><b>${link(r.source_url,r.title)}</b><small>${e(r.source||'operator_import')} · retrieved ${e(r.retrieved_at||'unknown')}</small></td><td>${r.currency==='USD'?cash(r.ask):e(r.ask??'Unknown')+' '+e(r.currency||'currency unknown')}<small>${e(r.evidence_kind||'active_listing_only')}</small></td><td>${e(r.research_score)} / 100<small>Not expected profit</small></td><td>${badge(r.app_lead_id?'IN RESEARCH QUEUE':'SYNC PENDING',r.app_lead_id?'blue':'gold')}<small>Manual purchase review required</small></td><td><button data-action="discovery-evidence" data-id="${i}" class="secondary">Evidence →</button>${r.app_lead_id?` <button data-action="deal" data-id="${e(r.app_lead_id)}" class="secondary">Review →</button>`:''}</td></tr>`)):empty('Collector is ready; API keys are not connected.','Import an authorized saved listing CSV now, or configure your production eBay keyset later. No live listing has been fetched by this integration yet.')}<details><summary>Feed provenance and search health</summary>${json({source_counts:feed.source_counts,queries:feed.queries,warning:feed.warning})}</details></section>`}
function discoveryImportDialog(){drawer('Import listing evidence into discovery',`<p>Paste authorized saved listing rows. The collector and shared Store retain active asks as research evidence. Include source dates and currency; synthetic test rows must be labelled SYNTHETIC.</p><form id="discoveryImportForm"><label>CSV file<input type="file" id="discoveryCsvFile" accept=".csv,text/csv"></label><label>Listing CSV<textarea name="csv" id="discoveryCsvText" rows="10">listing_id,title,source_url,ask,currency,shipping,observed_at,retrieved_at
</textarea></label><button>Import & sync research queue</button><div class="formResult"></div></form>`);$('discoveryCsvFile').onchange=async ev=>$('discoveryCsvText').value=await ev.target.files[0].text()}
function research(){let a=S.audit;return pageTop('SOURCE-GROUNDED / IMMUTABLE','The evidence behind the edge.','Original observations, grade histories, failures and monthly business records.',`<button data-action="audit">↻ Audit local sources</button>`)+
discoveryPanel()+`<div class="grid stats">${stat('RAW SOURCE ROWS',S.research.length,'Not a unique physical-card count')}${stat('EXACT FILE HASHES',a.unique_sha256||0,`${(a.exact_duplicate_groups||[]).length} duplicate groups`)}${stat('CANONICAL SOURCES',(a.canonical_packs||[]).filter(r=>r.status==='VERIFIED').length+' / 18','Unavailable packs remain missing')}${stat('TRAINING PAIRS',a.verified_pre_buy_photo_outcome_pairs||0,'Verified before-photo / later-outcome pairs','gold')}</div>
<div class="grid two"><section class="panel"><h2>Source coverage</h2>${(a.canonical_packs||[]).map(r=>`<div class="source-card"><h3>${e(r.name)}</h3>${badge(r.status,r.status==='VERIFIED'?'blue':'')} ${r.rows===undefined?'':`<small>${r.rows} source rows</small>`}</div>`).join('')}</section><section class="panel"><h2>Data integrity</h2><p>546-card and two-year studies are aggregate context. One Piece remains a separate game. Same-name cards remain separate unless evidence links the actual copy.</p><div class="callout">Missing locally: canonical full transport, earlier 135-photo Master_Index and the separately collected 28-video transcript ZIP. The linked folder contains its own transcript records; those are indexed without inventing the absent corpus.</div><h3>Compact ZIP verification</h3>${(a.compact_zip_comparison||[]).map(r=>`<p>${e(r.archive)}<br>${r.matched_members} matching members · ${r.different_members} different</p>`).join('')}<div class="actions"><button data-action="audit-report" class="secondary">Open audit evidence</button><button data-action="rules" class="secondary">Fredy operating rules</button></div></section></div>
<section class="panel"><div class="panel-head"><h2>Original card observations</h2><button data-action="export" data-kind="source_record" class="secondary">Export provenance CSV</button></div><input id="researchSearch" placeholder="Search source records, cards, grades, failures…" aria-label="Search research"><div id="researchResults">${researchRows(S.research)}</div></section><section class="panel"><div class="panel-head"><div><h2>Raw recording evidence review</h2><p>${(S.video_frames||[]).length} clock-mapped previews. Preview pixels are review aids; decode original frames before card-only review.</p></div><button data-action="video-sample" class="secondary">Sample / resume videos</button></div><div class="image-grid">${(S.video_frames||[]).filter((r,i)=>i%10===0).slice(0,36).map(r=>`<button data-action="video-frame" data-id="${r.id}"><img loading="lazy" src="/api/image?id=${r.id}" alt="Review preview from original recording"><span>${e(r.video_id)} · source ~${r.source_seconds_estimated}s</span></button>`).join('')}</div></section><section class="panel"><h2>Local transcript versions</h2><p>${(S.transcripts||[]).length} captured caption records. Recaptures remain source observations, not new independent outcomes.</p>${(S.transcripts||[]).map(r=>`<div class="source-card">${link(r.url,r.video_id||r.source_member||'Source transcript')} <button data-action="transcript" data-id="${r.id}" class="quiet">Read captured text →</button></div>`).join('')}</section>`}
function researchRows(rows){return table(['SOURCE CARD','REPORTED PATH','PROVENANCE',''],rows.map(r=>`<tr><td><b>${e(r.name||'Unresolved identity')}</b><small>${e(r.variant||'Variant unknown')}</small></td><td>${e(r.original_grade_path||'?')} → ${e(r.reported_final_grade||'?')}<small>${e(r.game)} · creator reported</small></td><td>${e(r.source_label)}<small>${e(r.timestamp||'No exact timestamp')} · row ${r.source_row}</small></td><td><button class="secondary" data-action="source" data-id="${r.id}">Evidence →</button></td></tr>`))}
function vault(){return pageTop('PSA VAULT / OWNER WORKSPACE','Custody to cash.','Collection, sourced exit comparisons, manual status evidence and receipt reconciliation.',`<button data-action="import-holdings">+ Import collection</button>`)+
`<div class="grid stats">${stat('OWNED HOLDINGS',S.holdings.length,'Private local records')}${stat('PAYOUT PENDING',S.holdings.filter(r=>r.unpaid).length,'Actual receipts required')}${stat('VERIFIED RECEIPTS',S.holdings.reduce((n,h)=>n+h.payouts.length,0),'Deduplicated by receipt and listing')}${stat('ACCOUNT SYNC','Manual','No private Vault API claimed')}</div>
<section class="panel"><div class="panel-head"><div><h2>My collection</h2><p>Already vaulted, eligible and PSA-consigned are distinct evidence fields.</p></div><a class="button secondary" href="https://app.collectors.com/collection" target="_blank" rel="noopener">Open official collection ↗</a></div>${holdingTable()}<div class="actions"><button data-action="new-holding" class="secondary">Add owned item</button><button data-action="export" data-kind="holding" class="secondary">Export collection</button></div></section>
<div class="grid two"><section class="panel"><h2>Vault vs withdrawal</h2><p>Compare gross sale estimates, actual offers, insured shipping, early fees and regrade expenses. Unknown tax stays unknown.</p>${vaultForm()}<div id="vaultResult"></div></section><section class="panel"><h2>Owner action center</h2>${health('Discover & verify','Record listing, eligibility and actual custody evidence','MANUAL')}${health('Sell via PSA','Auction / Buy It Now; single PSA fee','OFFICIAL SITE')}${health('Partner Offer','Actual amount and expiry; zero advertised offer fee','OWNER INPUT')}${health('Withdraw or transfer','Track externally completed actions with dated evidence','NO AUTOMATION')}${health('Stripe payout','Match owned item → listing → verified receipt','RECONCILE')}<div class="actions"><a class="button secondary" target="_blank" rel="noopener" href="https://www.psacard.com/info/psa-vault">Current PSA terms ↗</a><a class="button secondary" target="_blank" rel="noopener" href="https://www.psacard.com/info/consignment-rates">Consignment rates ↗</a></div><div class="callout">Shipping schedule begins October 29, 2026. Earlier dates need an actual quote. Fee tiers outside the published $100–$499 example require a quoted percentage. Tax treatment requires actual account/jurisdiction inputs.</div></section></div>`}
function holdingTable(){return S.holdings.length?table(['OWNED ITEM','CUSTODY','BASIS / CASH','WORKFLOW'],S.holdings.map(h=>`<tr><td><b>${e(h.name||h.item_id)}</b><small>${e(h.grader)} ${e(h.current_grade)} · cert ${e(h.cert||'unknown')}</small></td><td>${badge(h.current_state,'blue')}<small>Verified ${e(h.observed_at)}</small></td><td>${cash(h.all_in_cost)}<small>Verified cash: ${cash(h.realized_cash)}</small></td><td><button data-action="holding" data-id="${h.id}" class="secondary">Timeline</button> <button data-action="custody" data-id="${h.id}" class="secondary">Status</button> <button data-action="receipt" data-id="${h.id}" class="secondary">Receipt</button> <button data-action="grade-event" data-id="${h.id}" class="secondary">Grade result</button></td></tr>`)):empty('Collection is empty','Import your own Vault or acquisition records with source links and verification dates. No fake holdings are seeded.')}
function vaultForm(){const d=new Date().toLocaleDateString('en-CA',{timeZone:'America/New_York'});return `<form id="vaultForm"><div class="form-grid">${field('asof','Quote date','date',d,true)}${field('vaulted_at','Initial vault date','date')}${field('basis','Original all-in basis (USD)','number')}${field('sale_price','Estimated intact sale (USD)','number')}${field('psa_fee_pct','Quoted PSA fee % (leave blank if unknown)','number')}${field('declared_value','Insured declared value (USD)','number')}${field('shipping_quote','Pre-Oct 29 actual shipping quote','number')}${field('offer_amount','Actual private offer amount','number')}${field('offer_expires','Actual offer expiry','date')}${field('offer_evidence','Actual offer evidence reference')}${field('tax','Potential tax quote (explicit zero allowed)','number')}${field('own_fee_pct','Own sale venue total fee %','number')}${field('sale_shipping','Own sale shipping','number')}${field('contingency','Contingency','number')}${field('regrade_exit','Hypothetical regraded exit','number')}${field('grading','Grading fee','number')}${field('grading_shipping','Grader round-trip shipping','number')}${field('insurance','Grading transit insurance','number')}${field('upcharge','Service upcharge','number')}${field('transfer_amount','External transfer payment quote','number')}${field('transfer_fee','External transfer fee quote','number')}${field('transfer_evidence','External transfer quote / payment evidence')}</div>${check('card_listed','Card is currently listed on eBay')}<button>Compare exits</button></form>`}
function portfolio(){return pageTop('PORTFOLIO / CASH CYCLE','Know what is actually liquid.','Owned copies, submission history, full cost basis and independently verified receipts.')+
`<div class="grid stats">${stat('KNOWN BASIS',cash(S.budget.all_in_committed),'Missing bases excluded, never zero-filled')}${stat('UNRESOLVED BASIS',S.budget.unknown_cost_holdings,'Complete cost evidence needed')}${stat('RESERVE','$5,000','Never allocated')}${stat('ACTUAL RECEIPTS',cash(S.holdings.reduce((n,r)=>n+Number(r.realized_cash||0),0)),'Verified owner receipts only')}</div><section class="panel"><h2>Inventory & submission queue</h2>${holdingTable()}<div class="actions"><button data-action="new-holding">+ Add physical copy</button><button data-action="export" data-kind="vault_event" class="secondary">Export event history</button><button data-action="export" data-kind="payout" class="secondary">Export receipt ledger</button></div></section><section class="panel"><h2>Multi-route financial workbench</h2><p>Compare against selling the original slab, with every required cost explicit. Sensitivity and hypothetical profit are not measured conversion odds.</p><div class="actions"><button data-action="financial">Open route calculator →</button><button data-action="venues" class="secondary">Compare venue cash cycles</button><button data-action="retry" class="secondary">Stop vs retry</button></div></section>`}
function market(){return pageTop('MARKET DATA / EXACT EVIDENCE','Asks are not sales.','Authorized active listings, actual dated completed sales, exact variants and provider status.',`<button data-action="import-sales">+ Import sold evidence</button>`)+
`<div class="grid two"><section class="panel"><h2>Provider capabilities</h2>${Object.entries(S.providers).map(([name,p])=>health(name.replaceAll('_',' '),p.capability||p.mode||'',p.credentials_present?'CREDENTIAL SET':p.mode||'NO CREDENTIAL')).join('')}<div class="actions"><button data-action="ebay" class="secondary">Search eBay Browse</button><button data-action="cert" class="secondary">Verify PSA cert</button></div></section><section class="panel"><h2>Evidence quality</h2><p>Sales preserve exact card identity, grader, actual accepted price, date, currency and original transaction link. Mirrored receipts and sale IDs are deduplicated. Active asks and indexes never enter the completed-sale estimator.</p><div class="callout">Rapidash #62 nonholo, #62 reverse and #26 holo are separate identities. Weak or incomplete matching leaves a lead unapproved.</div><button data-action="comp-query" class="secondary">Query exact sold statistics</button></section></div><section class="panel"><div class="panel-head"><h2>Dated sold observations</h2><button data-action="export" data-kind="sale" class="secondary">Export CSV</button></div>${S.sales.length?table(['CARD / VARIANT','GRADE','PRICE','SALE DATE','SOURCE'],S.sales.map(r=>`<tr><td>${e(r.name)}<small>${e(r.set)} · #${e(r.number)} · ${e(r.finish)} · ${e(r.language)}</small></td><td>${e(r.grader)} ${e(r.grade)}</td><td>${cash(r.price)}<small>${e(r.currency)}</small></td><td>${e(r.sale_date)}</td><td>${link(r.source_url,'Original transaction')}</td></tr>`)):empty('No completed-sale evidence imported','Import actual Product Research records or permitted marketplace exports. Creator valuations are retained in Research Lab, not presented as current comps.')}</section>`}
function models(){let labels=S.reviews.filter(r=>r.type==='training_label'),latest=S.models.at(-1),test=latest?.metrics?.test;return pageTop('MODEL LAB / MEASURED VALIDATION','Train only what the evidence supports.','Paired front/back CNN baseline · connected physical-card and video holdouts · no paid remote inference.')+
`<div class="grid stats">${stat('CURATED LABELS',labels.length,'Rights, outcome and stage reviewed')}${stat('REAL TRAINED MODELS',S.models.length,'Synthetic artifacts excluded')}${stat('FROZEN TEST ACCURACY',test?(test.accuracy*100).toFixed(1)+'%':'Unavailable',test?`n=${test.count} · selected-source experimental holdout`:'No real-data accuracy is claimed','gold')}${stat('CALIBRATION','Unestablished','No numeric PSA10 probability')}</div><div class="grid two"><section class="panel"><h2>Launch supervised training</h2><p>One reviewed front/back pair per physical copy. At least five independent connected video groups are required; One Piece and post-outcome images are excluded.</p><form id="trainForm"><div class="form-grid">${sel('grader','Target grader',['PSA','CGC','BGS'])}${field('epochs','Epochs (1–200)','number','4',true)}</div><button>Validate dataset & train locally</button></form><div id="trainResult"></div><div class="callout">The current architecture is a modest 256px paired CNN baseline. High-fidelity multi-scale inspection and a validated physical-condition model remain uncompleted until eligible data exists.</div></section><section class="panel"><h2>Backtest coverage</h2>${health('Split policy','Connected specimen / video / cert / source / image groups','DETERMINISTIC','blue')}${health('Metrics','Confusion, MAE, F1, PSA10 false positives, Wilson intervals','IMPLEMENTED','blue')}${health('Financial replay','Point-in-time sold comps and full costs required','UNAVAILABLE','gold')}${health('Original grade baseline','Reported only when original labels are known','CONDITIONAL')}<a href="/api/grader-report" target="_blank">Open current dataset gap report ↗</a></section></div>${latest?`<section class="panel"><h2>Latest measured experimental evaluation</h2><p>${e(latest.grader)} · ${e(latest.training_status)} · source-selected evidence does not establish population-wide grading accuracy.</p>${json(latest.metrics)}<details><summary>Model provenance and checkpoint</summary>${json(latest)}</details></section>`:''}<section class="panel"><h2>Local jobs</h2>${Object.values(S.jobs).length?Object.values(S.jobs).map(j=>`<div class="status-row"><div>◎</div><div class="grow"><b>${e(j.name)}</b><small>${e(j.started_at)}</small></div>${badge(j.status)}<button class="secondary" data-action="job-log" data-id="${j.id}">View log</button></div>`).join(''):empty('No running training or audit job','Jobs run in ordinary local Python processes. Training outputs retain source hashes, specimen splits, environment, metrics and checkpoint hash.')}</section>`}
function settings(){return pageTop('SETTINGS / FIRST-RUN CHECKS','A private workspace, by default.','Local data paths, clear provider permissions and reproducible startup.')+
`<div class="grid two"><section class="panel"><h2>Setup checklist</h2>${health('Source directory',S.audit.dataset||'Not configured',S.audit.source_files?'CONNECTED':'MISSING',S.audit.source_files?'blue':'red')}${health('Private SQLite store','File permissions 0600 · audit trail','LOCAL','blue')}${health('Model setup','PyTorch / torchvision / Pillow; MPS or CPU','LOCAL')}${health('eBay access','EBAY_ENABLED and EBAY_PRODUCTION_APPROVED must both be true','EXPLICIT')}${health('Capital policy','$2,000 initial batch / $5,000 reserve','FIXED','green')}<div class="actions"><button data-action="audit" class="secondary">Audit data now</button><a class="button secondary" href="/classic">Classic fallback</a></div></section><section class="panel"><h2>Credentials remain local</h2><p>Configure environment variables in the launching terminal. Secret values never appear in UI, reports or request logs.</p>${json({EBAY_CLIENT_ID:'local secret',EBAY_CLIENT_SECRET:'local secret',EBAY_ENABLED:'true only when authorized',EBAY_PRODUCTION_APPROVED:'true only when actually approved',PSA_API_TOKEN:'optional authorized token'})}<p>Fanatics Collect and Arizona TCG support manual source imports. A general private PSA Vault API is unsupported.</p><button data-action="provider-details" class="secondary">View actual capability status</button></section></div><section class="panel"><h2>Operator corrections</h2><p>Notes, defects, identity decisions and labels are append-only. Corrections are reviewed before a new model is trained; deployment never silently changes from feedback.</p><button data-action="note" class="secondary">Add audit note</button><button data-action="export" data-kind="review" class="secondary">Export all reviews</button></section>`}
function drawer(title,body){$('drawerBody').innerHTML=`<div class="eyebrow">HOLY POKÉMON / REVIEW</div><h1>${e(title)}</h1>${body}`;$('drawer').showModal();bind($('drawer'))}
function formObject(form){let r=Object.fromEntries(new FormData(form));for(const el of form.querySelectorAll('[type=checkbox]'))r[el.name]=el.checked;return r}
function makeForm(id,fields,button='Save local evidence'){return `<form id="${id}"><div class="form-grid">${fields}</div><button>${button}</button><div class="formResult"></div></form>`}
function importDialog(kind){const examples={lead:'listing_id,title,url,ask,currency,observed_at,provider\n',sale:'transaction_id,source_url,observed_at,sale_date,evidence_kind,price,currency,provider,game,set,number,name,language,edition,finish,grader,grade,exact_variant_verified\n',holding:'item_id,name,grader,current_grade,cert,state,all_in_cost,vaulted_at,ebay_item_id,source_url,observed_at,provider\n'};drawer('Import '+kind+' records',`<p>Paste an authorized CSV or choose a local file. Source URL and observed_at are required. Unknown amounts remain blank.</p><form id="importForm"><input type="hidden" name="kind" value="${kind}"><label>CSV file<input type="file" id="csvFile" accept=".csv,text/csv"></label><label>Source rows<textarea name="csv" id="csvText" rows="10">${e(examples[kind]||'')}</textarea></label><button>Validate & import</button><div class="formResult"></div></form>`);$('csvFile').onchange=async ev=>$('csvText').value=await ev.target.files[0].text()}
function newLead(){drawer('Add a research lead',`<p>Keep imperfect leads visible. These fields describe an active ask or an observed listing, not a completed sale.</p>`+makeForm('newLeadForm',field('listing_id','Listing ID')+field('title','Card / title','text','',true)+field('url','Original HTTPS listing URL','url','',true)+field('ask','Asking price (USD)','number')+field('possible_best_exit','Hypothetical best-grade exit, if known','number')+field('observed_at','Observed date','date','',true)+sel('provider','Venue',['ebay','psa_vault','fanatics_collect','arizona_tcg','manual'])+sel('vault_status','Vault observation',['unknown','user_reported_yes','user_reported_no'])+sel('already_in_psa_vault','Already in PSA Vault',['unknown','yes','no'])+field('already_in_psa_vault_evidence','Badge / custody evidence reference')+sel('vault_eligible','Vault eligible at checkout',['unknown','yes','no'])+field('vault_eligible_evidence','Eligibility evidence reference')+sel('psa_consignment_listing','PSA consignment listing',['unknown','yes','no'])+field('psa_consignment_listing_evidence','Consignment evidence reference'))) }
function newHolding(){drawer('Add an owned physical card',`<p>Record acquisition evidence. A status entry records an action already completed by the owner; this app does not buy or transfer cards.</p>`+makeForm('newHoldingForm',field('item_id','Your stable item ID','text','',true)+field('name','Card name','text','',true)+sel('grader','Current holder',['PSA','CGC','BGS','SGC'])+field('current_grade','Actual current grade')+field('cert','Certificate number')+sel('state','Verified custody',['acquired_pending','vaulted','owner_possession','held','submitted_for_grading','consigned','listed_bin','listed_auction','sold_unpaid','payout_pending'])+field('all_in_cost','Verified all-in acquisition basis','number')+field('vaulted_at','Initial vault date','date')+field('ebay_item_id','Matched eBay item ID')+field('source_url','Receipt/account source URL','url','',true)+field('observed_at','Verified on','date','',true))) }
function deal(id){let r=S.leads.find(r=>r.id===id);drawer(r.title||r.name,`<p>${link(r.url||r.source_url,'Original listing')} · ${e(r.observed_at)}</p><div class="grid three">${stat('ASK',cash(r.ask),'Active ask only')}${stat('HYPOTHETICAL SPREAD',cash(r.research_spread),'Before full costs')}${stat('DECISION','Needs evidence','No buy authorization')}</div><h2>Evidence gaps</h2>${r.evidence_gaps.map(g=>`<span class="pill">${e(g.replaceAll('_',' '))}</span>`).join('')}<div class="actions"><button data-action="watch-lead" data-id="${id}">Save watch</button><button data-action="financial" class="secondary">Compare grade routes</button><button data-action="decision" data-id="${id}" class="secondary">Check manual readiness</button>${link(r.sold_search,'Exact sold search')}</div><h2>Recorded listing fields</h2>${json(r)}<form id="dealNote"><input type="hidden" name="subject" value="${id}"><label>Review note<textarea name="text" required></textarea></label><button>Save note</button><div class="formResult"></div></form>`)}
function financial(){let costs=['grading','grading_shipping','grading_insurance','upcharge','outbound_shipping','vault_withdrawal','vault_early_fee','vault_consignment_fixed','holding_cost','contingency'];drawer('Compare the original slab with a grade route',`<p>Enter an explicit zero where a cost is known not to apply. Blank costs prevent a false profit calculation.</p><form id="financeForm"><h2>Acquisition</h2><div class="form-grid">${['ask','buyer_shipping','purchase_tax','buyer_premium'].map(k=>field(k,k.replaceAll('_',' '),'number')).join('')}</div><h2>Intact original slab benchmark</h2><div class="form-grid">${field('original_exit','Exact original-grade sale estimate','number')}${field('original_fee','Original sale fee %','number')}${field('original_shipping','Original sale shipping','number')}</div><h2>Alternative route</h2><div class="form-grid">${sel('route','Route',['legacy_cgc_reholder','psa_intact_crossover_success','psa_intact_crossover_rejected','crack_psa_6','crack_psa_8','crack_psa_9','crack_psa_10','cgc_8_5','cgc_9','cgc_9_5','cgc_gem_10','cgc_pristine_10','bgs_9','bgs_9_5','bgs_10','repeat_regrade','raw_resale','hold'])}${field('exit_price','Alternative exit estimate','number')}${field('fee_pct','Alternative venue fee %','number')}${costs.map(k=>field(k,k.replaceAll('_',' '),'number')).join('')}</div><button>Calculate full-cost outcome</button><div class="formResult"></div></form>`)}
async function imageDrawer(id){let r=S.images.find(x=>x.id===id)||{name:'Original evidence image'};drawer('Review original photograph',`<p>${e(r.name)} · Click two opposite corners to define a full card-only crop. The original stays unchanged.</p><div class="image-stage" id="imageStage"><img id="reviewImage" src="/api/image?id=${id}" alt="Unaltered source photograph"><canvas id="cropCanvas"></canvas></div><div class="actions"><button id="assignFront" class="secondary">Use as front</button><button id="assignBack" class="secondary">Use as back</button><a href="/api/image?id=${id}" target="_blank" class="button secondary">Full resolution ↗</a><button id="imageQA" class="secondary">Measure photo QA</button></div><div id="qaResult"></div><form id="cropForm"><input type="hidden" name="id" value="${id}"><div class="form-grid">${field('left','Card left (pixels)','number')}${field('top','Card top','number')}${field('right','Card right','number')}${field('bottom','Card bottom','number')}</div>${check('card_only_verified','I reviewed this full-card crop: no grade labels, certs, slab branding or result overlays; every card edge is preserved.')}<button>Save derived crop</button><div class="formResult"></div></form><hr><h2>Visible defect annotation</h2><form id="defectForm"><input type="hidden" name="id" value="${id}"><div class="form-grid">${sel('defect','Condition factor',['whitening','corner_wear','chipping','scratches','print_lines','stains','dent','crease','gloss','foil_texture','obstruction','centering'])}${sel('visibility','Visibility',['unknown','seen','not_visible'])}${field('region','Region / location')}${sel('severity','Severity',['unknown','minor','moderate','severe'])}${field('evidence','Observation and uncertainty')}</div><button>Append annotation</button><div class="formResult"></div></form>`);
$('assignFront').onclick=()=>{selectedFront=id;$('drawer').close();render()};$('assignBack').onclick=()=>{selectedBack=id;$('drawer').close();render()};$('imageQA').onclick=async()=>{try{$('qaResult').innerHTML=json(await api('image-qa',{id}))}catch(err){toast(err.message)}};
let points=[];const im=$('reviewImage');im.onclick=ev=>{const rect=im.getBoundingClientRect();let point=[Math.round((ev.clientX-rect.left)*im.naturalWidth/rect.width),Math.round((ev.clientY-rect.top)*im.naturalHeight/rect.height)];if(points.length===2)points=[];points.push(point);if(points.length===2){let [a,b]=points,box=[Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.max(a[0],b[0]),Math.max(a[1],b[1])];['left','top','right','bottom'].forEach((name,i)=>$('cropForm').elements[name].value=box[i]);let c=$('cropCanvas');c.width=im.clientWidth;c.height=im.clientHeight;let ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.strokeStyle='#4089ff';ctx.lineWidth=2;ctx.strokeRect(box[0]*c.width/im.naturalWidth,box[1]*c.height/im.naturalHeight,(box[2]-box[0])*c.width/im.naturalWidth,(box[3]-box[1])*c.height/im.naturalHeight)}};
}
function labelDialog(){if(!selectedFront||!selectedBack)return toast('Choose front and back originals first.');drawer('Link a real later grading outcome',`<p>Both images need reviewed card-only crops first. Source rights and the before-buy/later-grade linkage must be explicit. Creator predictions are not actual outcomes.</p>`+makeForm('labelForm',field('physical_specimen_id','Stable physical card ID','text','',true)+field('source_video_id','Original video / independent source group','text','',true)+sel('grader','Target grading company',['PSA','CGC','BGS'])+field('grade','Actual later grade (CGC: Pristine 10 distinct)','text','',true)+field('original_grade','Original numeric grade, if known')+field('cert','Physical card cert, if known')+field('outcome_evidence','Actual later outcome evidence pointer','text','',true)+sel('rights_basis','Training rights basis',['explicit_permission','self_photographed','verified_permissive_license'])+field('rights_evidence','Training permission / license evidence','text','',true)+check('pre_decision_visible','Both photographs were available BEFORE the decision being predicted')+check('outcome_verified','I verified the later actual grading result for this same physical card')))}
function compDialog(){let fields=['game','year','set','number','denominator','name','language','edition','finish','stamp','error_variant','art_version','grader','grade','designation','label_era'];drawer('Exact completed-sale statistics',makeForm('compForm',fields.map(k=>field(k,k.replaceAll('_',' '))).join(''),'Query 30 / 90 / 180 days'))}
function simpleDialog(title,id,fields,button){drawer(title,makeForm(id,fields,button))}
function venueDialog(){drawer('Compare fees, liquidity and capital time',`<p>Paste dated venue quotes. Every cost and days_to_cash must be explicit. PSA consignment uses its single applicable fee.</p><form id="venueForm"><div class="form-grid">${field('basis','Full owned or acquisition basis','number')}${field('annual_capital_pct','Annual capital carrying cost %','number')}</div><label>Dated venue quotes (JSON array)<textarea name="venues" rows="14">[
  {"venue":"ebay", "gross":null, "fee_pct":null, "fixed_fee":null, "shipping":null, "insurance":null, "tax":null, "days_to_cash":null, "source_url":"", "effective_at":""},
  {"venue":"fanatics_collect", "gross":null, "fee_pct":null, "fixed_fee":null, "shipping":null, "insurance":null, "tax":null, "days_to_cash":null, "source_url":"", "effective_at":""},
  {"venue":"arizona_tcg", "gross":null, "fee_pct":null, "fixed_fee":null, "shipping":null, "insurance":null, "tax":null, "days_to_cash":null, "source_url":"", "effective_at":""}
]</textarea></label><button>Compare cash cycles</button><div class="formResult"></div></form>`)}
function decisionDialog(id){let lead=S.leads.find(r=>r.id===id);drawer('Evidence-based manual readiness',`<p>This evaluates research completeness. It never authorizes a purchase. Require three recent exact exit sales, original-grade fallback, full success/failure costs, ≤$200 downside and shared $2,000 capital.</p><form id="decisionForm"><input type="hidden" name="lead_id" value="${id}"><h2>Exact card identity</h2><div class="form-grid">${['game','year','set','number','denominator','name','language','edition','finish','stamp','error_variant','art_version'].map(k=>field(k,k.replaceAll('_',' '),'text',lead[k]||'')).join('')}${field('exit_grader','Target company')}${field('exit_grade','Target numeric grade')}${field('exit_designation','Target designation (Gem Mint / Pristine)')}${field('exit_label_era','Target holder era')}${field('original_grader','Original company')}${field('original_grade','Original grade')}${field('original_designation','Original designation')}${field('original_label_era','Original holder era')}${field('seller_evidence','Seller and current listing evidence')}${field('front_evidence','Front photograph review reference')}${field('back_evidence','Back photograph review reference')}${field('condition_notes','Visible defects / hidden surface uncertainty')}</div>${check('identity_confirmed','I verified exact variant identity')}${check('seller_verified','I verified seller and current listing')}${check('photos_reviewed','I reviewed both original card sides')}<label>Full financial scenario JSON (listing + routes, including original, unchanged and downside branches)<textarea name="scenario" rows="8">{"listing":{},"routes":[]}</textarea></label><button>Evaluate readiness only</button><div class="formResult"></div></form>`)}
async function act(action,id,kind){try{switch(action){
case 'video-sample':toast('Local video sampling launched; source originals stay unchanged.');await api('video-sample',{});return load();
case 'video-frame':{let r=S.video_frames.find(r=>r.id===id);return drawer('Quarantined video review preview',`<p>Source video ${e(r.video_id)} · estimated source timestamp ${r.source_seconds_estimated}s. Clock alignment requires review. Stage, specimen and later outcome are unknown.</p><img style="max-width:100%" src="/api/image?id=${id}" alt="Derived review preview"><div class="actions"><button data-action="decode-frame" data-id="${id}">Decode unedited full-resolution frame</button></div>${json(r)}`)}
case 'decode-frame':{let r=await api('video-frame-full',{id});S=await (await fetch('/api/state')).json();return imageDrawer(r.id)}
case 'discovery-import':return discoveryImportDialog();
case 'discovery-sync':{let result=await api('discovery-sync',{});toast(`Queue sync: ${result.accepted||0} new snapshots, ${result.duplicates||0} duplicates`);return load()}
case 'discovery-scan':{let result=await api('discovery-scan',{});toast('One authorized read-only scan started. View local jobs in Model Lab.');return load()}
case 'discovery-evidence':{let r=S.discovery.leads[Number(id)];return drawer('Active listing research evidence',`<p>${link(r.source_url,r.title)}</p><p>Recorded asking price only. No verified sold comps, grading probability or purchase authorization is implied.</p>${json(r)}`)}
case 'transcript':{let r=S.transcripts.find(r=>r.id===id);return drawer('Captured source transcript',`<p>${link(r.url,r.video_id||'Source')} · captions may contain transcription errors.</p><pre>${e(r.text)}</pre>`)}
case 'decision':return decisionDialog(id);
case 'retry':return simpleDialog('Stop or pay for another attempt?','retryForm',field('stop_net','Net if sold now','number','',true)+field('success_exit','Net exit if next grade succeeds, before retry cost','number','',true)+field('failure_exit','Net exit if next grade fails, before retry cost','number','',true)+field('remaining_attempt_cost','All remaining retry costs','number','',true),'Calculate incremental sensitivity');
case 'venues':return venueDialog();
case 'import-leads':return importDialog('lead');case 'import-sales':return importDialog('sale');case 'import-holdings':return importDialog('holding');case 'new-lead':return newLead();case 'new-holding':return newHolding();case 'export':return download(kind);case 'deal':return deal(id);case 'image':return imageDrawer(id);case 'training-label':return labelDialog();case 'comp-query':return compDialog();case 'financial':return financial();
case 'monthly':return drawer('Monthly creator ledger',json(M));case 'audit-report':return drawer('Immutable source audit',json(S.audit));case 'provider-details':return drawer('Provider capability state',json(S.providers));
case 'source':{let r=S.research.find(r=>r.id===id);return drawer(r.name||'Source observation',`<p>Creator-reported source data. Unresolved links are not independent physical-card labels or verified payouts.</p>${json(r)}`)}
case 'holding':return drawer('Owned card timeline',json(S.holdings.find(r=>r.id===id)));
case 'rules':return drawer('Source-grounded business rules',json(await (await fetch('/api/rules')).json()));
case 'more-images':imageLimit+=24;return render();
case 'infer':if(!selectedFront)return toast('Choose a front photograph.');$('inference').innerHTML=json(await api('infer',{id:selectedFront,back_id:selectedBack}));return;
case 'watch-lead':{let r=S.leads.find(r=>r.id===id);await api('watch',{subject:r.title||r.name||r.id,notes:r.url||r.source_url});toast('Saved to local watchlist');return load()}
case 'audit':toast('Local audit launched. Check Model Lab for results.');await api('audit',{});return load();
case 'job-log':return drawer('Local job log',`<pre>${e(await (await fetch('/api/job-log?id='+id)).text())}</pre>`);
case 'ebay':return simpleDialog('Authorized active-listing search','ebayForm',field('query','eBay search query','text','',true),'Search approved Browse API');
case 'cert':return simpleDialog('PSA single-cert verification','certForm',field('cert','PSA certificate number','text','',true),'Verify cert');
case 'note':return simpleDialog('Append operator note','noteForm',field('subject','Subject / specimen / source ID','text','',true)+field('text','Correction / note','text','',true));
case 'custody':return simpleDialog('Record externally confirmed custody','custodyForm',`<input type="hidden" name="holding_id" value="${id}">`+sel('to','New verified application state',['acquired_pending','vaulted','owner_possession','held','consigned','listed_auction','listed_bin','sold_unpaid','sold_paid','payout_pending','paid_out','withdraw_requested','withdrawn','submitted_for_grading','transferred','unsold','relisted'])+field('source_ref','Dated evidence / receipt reference','text','',true)+field('event_at','Actual event timestamp','datetime-local','',true)+check('user_confirmed','I completed/verified this action in the official account; record locally only'));
case 'grade-event':return simpleDialog('Record an actual grading attempt','gradingEventForm',`<input type="hidden" name="holding_id" value="${id}">`+field('event_id','Unique submission / event ID','text','',true)+sel('grader','Result company',['PSA','CGC','BGS'])+field('grade','Actual result (CGC Pristine 10 stays distinct)','text','',true)+field('event_at','Actual grading date','date','',true)+field('source_ref','Observed result / submission evidence','text','',true)+field('paid_fee','Separately paid grading cost, if known','number')+field('notes','Attempt / defect notes')+check('outcome_verified','I verified this actual result for the same owned physical card')+check('fee_payment_verified','Any entered fee was separately paid and is not already in imported basis'));
case 'receipt':return simpleDialog('Reconcile an actual payout','payoutForm',`<input type="hidden" name="holding_id" value="${id}">`+field('listing_id','Matched sale listing ID','text','',true)+field('receipt_ref','Unique Stripe / receipt reference','text','',true)+field('paid_at','Receipt date','date','',true)+field('gross','Actual gross sale','number','',true)+field('psa_fee','Actual PSA fee','number','',true)+field('actual_payout','Actual received payout','number','',true)+check('receipt_verified','I verified the received cash and its match to this physical card'));
}}catch(err){toast(err.message)}}
function bind(root=document){root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action,el.dataset.id,el.dataset.kind));
let f=root.querySelectorAll('form');f.forEach(form=>form.onsubmit=async ev=>{ev.preventDefault();let body=formObject(form),output=form.querySelector('.formResult'),data;let button=form.querySelector('button');button.disabled=true;try{switch(form.id){
case 'retryForm':data=await api('retry',body);break;
case 'venueForm':data=await api('venues',{basis:body.basis,annual_capital_pct:body.annual_capital_pct,venues:JSON.parse(body.venues)});break;
case 'decisionForm':{let identity=Object.fromEntries(['game','year','set','number','denominator','name','language','edition','finish','stamp','error_variant','art_version'].map(k=>[k,body[k]]));data=await api('decision',{...body,identity,scenario:JSON.parse(body.scenario)});break}
case 'discoveryImportForm':data=await api('discovery-import',body);break;case 'importForm':data=await api('import',body);break;
case 'newLeadForm':data=await api('import',{kind:'lead',rows:[{...body,currency:'USD',source_url:body.url}]});break;
case 'newHoldingForm':data=await api('import',{kind:'holding',rows:[{...body,provider:'psa_vault',currency:'USD'}]});break;
case 'vaultForm':data=await api('vault-compare',body);$('vaultResult').innerHTML=table(['EXIT ROUTE','NET PROCEEDS','PROFIT IF SOLD','VS INTACT VAULT SALE'],data.routes.map(r=>`<tr><td>${e(r.route)}</td><td>${cash(r.net_proceeds)}</td><td>${cash(r.profit_if_sold)}</td><td>${cash(r.incremental_vs_vault_sale)}</td></tr>`))+`<details><summary>Fee sources and unknowns</summary>${json(data)}</details>`;return;
case 'cropForm':data=await api('crop',{id:body.id,box:[body.left,body.top,body.right,body.bottom].map(Number),card_only_verified:body.card_only_verified});break;
case 'defectForm':data=await api('annotation',body);break;
case 'labelForm':data=await api('training-label',{...body,image_id:selectedFront,back_id:selectedBack});break;
case 'trainForm':data=await api('train',body);$('trainResult').innerHTML=json(data);break;
case 'compForm':{let {grader,grade,designation,label_era,...identity}=body;data=await api('comps',{identity,grader,grade,designation,label_era});break}
case 'ebayForm':data=await api('ebay-search',body);break;case 'certForm':data=await api('cert',body);break;
case 'noteForm':case 'dealNote':data=await api('note',body);break;case 'custodyForm':data=await api('vault-transition',body);break;case 'payoutForm':data=await api('payout',body);break;case 'gradingEventForm':data=await api('grading-event',body);break;
case 'financeForm':{let listing=Object.fromEntries(['ask','buyer_shipping','purchase_tax','buyer_premium'].map(k=>[k,body[k]]));let zero=Object.fromEntries(['grading','grading_shipping','grading_insurance','upcharge','outbound_shipping','vault_withdrawal','vault_early_fee','vault_consignment_fixed','holding_cost','contingency'].map(k=>[k,'0']));data=await api('compare',{listing,routes:[{...zero,route:'sell_original',exit_price:body.original_exit,fee_pct:body.original_fee,outbound_shipping:body.original_shipping},{...body,exit_price_kind:'hypothetical_user_scenario'}]});break}
default:throw Error('Unsupported form')}
if(output)output.innerHTML=json(data);toast(data.errors?.length?'Import has validation errors; inspect results.':'Local operation completed');S=await (await fetch('/api/state')).json();if(form.id==='discoveryImportForm')render();
}catch(err){if(output)output.innerHTML=`<p class="callout">${e(err.message)}</p>`;else toast(err.message)}finally{button.disabled=false}});
if($('leadSearch')){const filter=()=>{let q=$('leadSearch').value.toLowerCase(),mode=$('leadSort').value,rows=S.leads.filter(r=>JSON.stringify(r).toLowerCase().includes(q));if(mode==='premium')rows=rows.filter(r=>Number(r.possible_best_exit)>=500).slice(0,20);else if(mode==='vault')rows=rows.filter(r=>r.vault_status==='user_reported_yes');$('leadResults').innerHTML=table(['CARD / SOURCE','ASK','UPSIDE CLUE','EVIDENCE',''],leadRows(rows.slice(0,mode==='premium'?20:50)));bind($('leadResults'))};$('leadSearch').oninput=filter;$('leadSort').onchange=filter}
if($('researchSearch'))$('researchSearch').oninput=()=>{$('researchResults').innerHTML=researchRows(S.research.filter(r=>JSON.stringify(r).toLowerCase().includes($('researchSearch').value.toLowerCase())));bind($('researchResults'))};
if($('imageSearch'))$('imageSearch').oninput=()=>{$('imageGallery').innerHTML=gallery(S.images.filter(r=>(r.name+' '+r.source).toLowerCase().includes($('imageSearch').value.toLowerCase())).slice(0,imageLimit));bind($('imageGallery'))};
for(let side of ['front','back'])if($(side+'Upload'))$(side+'Upload').onchange=async ev=>{try{let file=ev.target.files[0];if(!file)return;if(file.size>15e6)throw Error('15MB image limit');let reader=new FileReader();reader.onload=async()=>{try{let r=await api('upload',{name:file.name,base64:String(reader.result).split(',')[1]});if(side==='front')selectedFront=r.id;else selectedBack=r.id;S=await (await fetch('/api/state')).json();render();toast('Original preserved; photo QA available in review')}catch(err){toast(err.message)}};reader.readAsDataURL(file)}catch(err){toast(err.message)}};
}
$('theme').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('holyTheme',document.body.classList.contains('light')?'light':'dark')};if(localStorage.getItem('holyTheme')==='light')document.body.classList.add('light');$('refresh').onclick=()=>load().catch(err=>toast(err.message));$('closeDrawer').onclick=()=>$('drawer').close();window.onhashchange=render;load().catch(err=>{$('content').innerHTML=empty('Local service unavailable',err.message)});
